insert into public.vocabulary select * from jsonb_populate_recordset(null::public.vocabulary, $seed$[{"id":"access-w1","word":"timetable","translation":"der Stundenplan","translation_ru":"расписание","difficulty":"A2","theme":"School","definition":"A plan that shows when your lessons happen.","definition_de":"Ein Plan, der zeigt, wann deine Unterrichtsstunden stattfinden.","definition_ru":"План, который показывает, когда проходят уроки.","example":"English is on our timetable on Monday and Thursday."},{"id":"access-w2","word":"break","translation":"die Pause","translation_ru":"перемена","difficulty":"A2","theme":"School","definition":"A short time when you stop working and rest.","definition_de":"Eine kurze Zeit, in der du nicht arbeitest und dich ausruhst.","definition_ru":"Короткое время, когда можно отдохнуть от работы.","example":"We play outside during the morning break."},{"id":"access-w3","word":"subject","translation":"das Schulfach","translation_ru":"школьный предмет","difficulty":"A2","theme":"School","definition":"Something you study at school, such as English or maths.","definition_de":"Etwas, das du in der Schule lernst, zum Beispiel Englisch oder Mathe.","definition_ru":"То, что изучают в школе, например английский или математику.","example":"My favourite subject is science."},{"id":"access-w4","word":"borrow","translation":"ausleihen","translation_ru":"брать на время","difficulty":"A2","theme":"Everyday life","definition":"To use something and give it back later.","definition_de":"Etwas benutzen und später zurückgeben.","definition_ru":"Взять что-то попользоваться и позже вернуть.","example":"Can I borrow your pencil, please?"},{"id":"access-w5","word":"helpful","translation":"hilfsbereit","translation_ru":"готовый помочь","difficulty":"A2","theme":"Emotions","definition":"Ready to help someone.","definition_de":"Bereit, jemandem zu helfen.","definition_ru":"Тот, кто охотно помогает другим.","example":"My friend was helpful when I missed a lesson."},{"id":"access-w6","word":"practise","translation":"üben","translation_ru":"практиковаться","difficulty":"A2","theme":"Hobbies","definition":"To do something again so you get better at it.","definition_de":"Etwas wiederholen, um besser darin zu werden.","definition_ru":"Повторять действие, чтобы получалось лучше.","example":"I practise English for ten minutes after school."}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.quiz_questions select * from jsonb_populate_recordset(null::public.quiz_questions, $seed$[{"id":"access-q1","lesson_id":"week-2","topic":"Present simple","difficulty":"Beginner","type":"choice","prompt":"We ___ English on Mondays.","options":["has","have","having"],"answer":"have","explanation":"Use have with I, you, we, and they.","explanation_de":"Bei I, you, we und they steht have.","explanation_ru":"С I, you, we и they используется have."},{"id":"access-q2","lesson_id":"week-3","topic":"Questions and negatives","difficulty":"Beginner","type":"choice","prompt":"Can you ___ me, please?","options":["help","helps","helping"],"answer":"help","explanation":"After can, use the base form of the verb.","explanation_de":"Nach can steht die Grundform des Verbs.","explanation_ru":"После can используется начальная форма глагола."},{"id":"access-q3","lesson_id":"week-3","topic":"Subject–verb agreement","difficulty":"Beginner","type":"choice","prompt":"There ___ two books on the desk.","options":["is","are","am"],"answer":"are","explanation":"Two books is plural, so use there are.","explanation_de":"Two books steht im Plural. Deshalb there are.","explanation_ru":"Two books — множественное число, поэтому there are."},{"id":"access-q4","lesson_id":"week-2","topic":"Past simple","difficulty":"Beginner","type":"blank","prompt":"Yesterday, I ___ (play) football after school.","options":[],"answer":"played","explanation":"Yesterday is in the past. Add -ed to the regular verb play.","explanation_de":"Yesterday liegt in der Vergangenheit. Bei play kommt -ed dazu.","explanation_ru":"Yesterday указывает на прошлое. К правильному глаголу play добавляем -ed."}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.reading_passages select * from jsonb_populate_recordset(null::public.reading_passages, $seed$[{"id":"access-r1","title":"After-school plans","level":"A2 · School life","body":"On Tuesdays, Sam stays at school after his last lesson. He is in the school gardening club. At first, he joined because his friend Mia wanted to go. Now he enjoys growing vegetables.\n\nLast week, it rained, so the club could not work outside. Their teacher brought small pots into the classroom. Everyone planted a seed and put a name on their pot.\n\nSam put his pot by the window. He checks it every morning. “I used to think plants were boring,” he says. “Now I want to know how much my plant grows each day.”"}]$seed$::jsonb) on conflict (id) do nothing;
insert into public.reading_questions select * from jsonb_populate_recordset(null::public.reading_questions, $seed$[{"id":"access-rq1","prompt":"Why did Sam first join the club?","options":["His friend wanted to go","He wanted to miss a lesson","His teacher asked him to"],"answer":"His friend wanted to go","explanation":"Sam first joined because his friend Mia wanted to go.","explanation_de":"Am Anfang ging Sam mit, weil seine Freundin Mia hingehen wollte.","explanation_ru":"Сначала Сэм записался, потому что его подруга Мия хотела пойти.","passage_id":"access-r1"},{"id":"access-rq2","prompt":"What did the club do when it rained?","options":["They went home","They planted seeds inside","They played football"],"answer":"They planted seeds inside","explanation":"The teacher brought pots into the classroom, and everyone planted a seed.","explanation_de":"Die Lehrkraft brachte Töpfe ins Klassenzimmer. Alle pflanzten einen Samen.","explanation_ru":"Учитель принёс горшки в класс, и каждый посадил семечко.","passage_id":"access-r1"},{"id":"access-rq3","prompt":"How did Sam’s feelings about plants change?","options":[],"answer":"He thought plants were boring, but now he is interested in them.","explanation":"Use your own words. Explain what he felt before and what he feels now.","explanation_de":"Benutze eigene Worte. Erkläre, was er früher dachte und was er jetzt denkt.","explanation_ru":"Ответь своими словами. Объясни, что Сэм думал раньше и что думает теперь.","passage_id":"access-r1"}]$seed$::jsonb) on conflict (id) do nothing;
